169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
172	        validateRequiredOwnerFields(ownerFieldsDto);
173	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
174	        LocalDate suppliedOrDefaultDate =
175	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
176	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
177	        rejectDailyLimitExceeded(registrationDate);
178	        rejectCityAtCapacity(ownerFieldsDto.getCity());
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        validatePostcode(owner.getCity(), owner.getPostcode());
182	        owner.setAddress(normalizeAddress(owner.getAddress()));
183	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
184	        owner.setTelephone(normalizedTelephone);
185	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
186	        owner.setEmail(normalizeEmail(owner.getEmail()));
187	        rejectDuplicateIdentity(owner);
188	        applyPossibleDuplicate(owner, declaredHouseholdMember);
189	        owner.setRegistrationDate(registrationDate);
190	        owner.setCustomerCode(
191	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
192	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
193	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
194	        this.clinicService.saveOwner(owner);
195	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
196	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
197	        OwnerDto ownerDto = toOwnerDto(owner);
198	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
199	        headers.setLocation(UriComponentsBuilder.newInstance()
200	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
201	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
202	    }
