297	    /**
298	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
299	     * offending field is collected so the caller learns exactly which values must be supplied.
300	     *
301	     * @param ownerFieldsDto the submitted owner payload
302	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
303	     *         telephone is missing or blank
304	     */
305	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
306	        List<String> missingFields = new ArrayList<>();
307	        if (isBlank(ownerFieldsDto.getFirstName())) {
308	            missingFields.add("firstName");
309	        }
310	        if (isBlank(ownerFieldsDto.getLastName())) {
311	            missingFields.add("lastName");
312	        }
313	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
314	            missingFields.add("address");
315	        }
316	        if (isBlank(ownerFieldsDto.getCity())) {
317	            missingFields.add("city");
318	        }
319	        if (isBlank(ownerFieldsDto.getTelephone())) {
320	            missingFields.add("telephone");
321	        }
322	        if (!missingFields.isEmpty()) {
323	            throw new MissingOwnerFieldsException(missingFields);
324	        }
325	    }
