331	    /**
332	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
333	     * current date. A registration date may not lie in the future; a value equal to today or in the
334	     * past is accepted, and an absent date is left to default to the server date.
335	     *
336	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
337	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
338	     */
339	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
340	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
341	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
342	        }
