345	    /**
346	     * Counts the existing owners who, before this create, already share the given first and last name.
347	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
348	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
349	     * case or spacing still count as the same name.
350	     *
351	     * @param firstName the first name of the owner being created
352	     * @param lastName the last name of the owner being created
353	     * @return the number of existing owners sharing both names (zero when none)
354	     */
355	    private int countNamesakes(String firstName, String lastName) {
356	        String first = normalizeHouseholdField(firstName);
357	        String last = normalizeHouseholdField(lastName);
358	        return (int) this.clinicService.findAllOwners().stream()
359	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
360	                && normalizeHouseholdField(existing.getLastName()).equals(last))
361	            .count();
362	    }
