364	    /**
365	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
366	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
367	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
368	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
369	     * more owners the create is rejected as a conflict.
370	     *
371	     * @param city the city of the owner being created
372	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
373	     */
374	    /**
375	     * Rejects an owner create once the maximum number of owners have already been registered on the
376	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
377	     * which is always a business day (a weekend effective date is rolled forward to the following
378	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
379	     * business day the create is rejected as too many requests. Because a weekend effective date is
380	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
381	     *
382	     * @param businessDay the adjusted business day the owner being created would be registered on
383	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
384	     */
385	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
386	        long ownersOnDay = this.clinicService.findAllOwners().stream()
387	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
388	            .count();
389	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
390	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
391	        }
392	    }
393	
394	    /**
395	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
396	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
397	     * was supplied on the request or defaulted to the server's current date.
398	     *
399	     * @param date the effective registration date (supplied or defaulted)
400	     * @return the same date when it is a weekday, otherwise the following Monday
401	     */
402	    /**
403	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
404	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
405	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
406	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
407	     *
408	     * @return {@code true} when more than the threshold number of owners are already registered on
409	     *         today's business day, otherwise {@code false}
410	     */
411	    private boolean isBulkSignupWarningActive() {
412	        LocalDate today = toBusinessDay(LocalDate.now());
413	        long ownersToday = this.clinicService.findAllOwners().stream()
414	            .filter(existing -> today.equals(existing.getRegistrationDate()))
415	            .count();
416	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
417	    }
418	
419	    private LocalDate toBusinessDay(LocalDate date) {
420	        return switch (date.getDayOfWeek()) {
421	            case SATURDAY -> date.plusDays(2);
422	            case SUNDAY -> date.plusDays(1);
423	            default -> date;
424	        };
425	    }
