427	    private void rejectCityAtCapacity(String city) {
428	        String normalizedCity = normalizeHouseholdField(city);
429	        long ownersInCity = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
431	            .count();
432	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
433	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
434	        }
435	    }
