437	    /**
438	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
439	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
440	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
441	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). The code carries no
442	     * sequence number; two owners resolve to the same code only when they share a region and produce the
443	     * same telephone-and-last-name hash.
444	     *
445	     * @param postcode the owner's postcode, used first to derive the region
446	     * @param city the owner's city, used to derive the region when the postcode maps to none
447	     * @param normalizedTelephone the owner's normalized (E.164) telephone
448	     * @param lastName the owner's last name
449	     * @return the formatted customer code
450	     */
451	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
452	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
453	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
454	        return region + "-" + hash8;
455	    }
