457	    /**
458	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
459	     * customerCode is the owner's customer code and YY is the last two digits of the
460	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
461	     *
462	     * @param customerCode the owner's customer code
463	     * @param registrationDate the owner's registration date
464	     * @return the formatted membership number
465	     */
466	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
467	        String yy = String.format("%02d", registrationDate.getYear() % 100);
468	        return customerCode + "-M" + yy;
469	    }
