471	    /**
472	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
473	     * country calling code. Australia ('+61') uses 9 national digits and the North American
474	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
475	     * E.164 length (8 to 15 digits overall).
476	     */
477	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
478	        java.util.Map.of("61", 9, "1", 10);
479	
480	    /**
481	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
482	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
483	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
484	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
485	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
486	     * E.164 string is what gets stored and returned.
487	     *
488	     * @param telephone the raw telephone value from the request
489	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
490	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
491	     *         national number has the wrong length for its country code
492	     */
493	    private String normalizeTelephone(String telephone) {
494	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
495	        String e164;
496	        if (cleaned.startsWith("+")) {
497	            e164 = cleaned;
498	        } else {
499	            String national = cleaned;
500	            if (national.startsWith("0")) {
501	                national = national.substring(1);
502	            }
503	            e164 = "+61" + national;
504	        }
505	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
506	            throw new InvalidOwnerFieldsException(List.of("telephone"));
507	        }
508	        validateNationalNumberLength(e164);
509	        return e164;
510	    }
511	
512	    /**
513	     * Rejects an E.164 telephone whose national number does not have the exact length its country
514	     * calling code requires. The digits after the leading '+' are split into the longest matching
515	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
516	     * code is known and the national number's length differs from the required count the telephone is
517	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
518	     *
519	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
520	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
521	     */
522	    private void validateNationalNumberLength(String e164) {
523	        String digits = e164.substring(1);
524	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
525	            String countryCode = digits.substring(0, codeLength);
526	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
527	            if (requiredNationalLength != null) {
528	                int nationalLength = digits.length() - codeLength;
529	                if (nationalLength != requiredNationalLength) {
530	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
531	                }
532	                return;
533	            }
534	        }
535	    }
536	
537	    /**
538	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
539	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
540	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
541	     * stored and returned is the value lower-cased.
542	     *
543	     * @param email the raw email value from the request, or {@code null} when none was supplied
544	     * @return the lower-cased email, or {@code null} when no email was supplied
545	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
546	     *         its domain is on the disposable-domain blocklist
547	     */
548	    private String normalizeEmail(String email) {
549	        if (email == null || email.isBlank()) {
550	            return null;
551	        }
552	        if (!EMAIL_PATTERN.matcher(email).matches()) {
553	            throw new InvalidOwnerFieldsException(List.of("email"));
554	        }
555	        String normalized = email.toLowerCase(Locale.ROOT);
556	        String domain = normalized.substring(normalized.indexOf('@') + 1);
557	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
558	            throw new InvalidOwnerFieldsException(List.of("email"));
559	        }
560	        return normalized;
561	    }
562	
563	    /**
564	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
565	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
566	     * When present it must be exactly four digits and, when the owner's city maps to a known region
567	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
568	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
569	     * region accepts any four-digit postcode.
570	     *
571	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
572	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
573	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
574	     *         for the city's region
575	     */
576	    private void validatePostcode(String city, String postcode) {
577	        if (postcode == null || postcode.isBlank()) {
578	            return;
579	        }
580	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
581	            throw new InvalidOwnerFieldsException(List.of("postcode"));
582	        }
583	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
584	        if (range == null) {
585	            return;
586	        }
587	        int value = Integer.parseInt(postcode);
588	        if (value < range[0] || value > range[1]) {
589	            throw new InvalidOwnerFieldsException(List.of("postcode"));
590	        }
591	    }
592	
593	    /**
594	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
595	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
596	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
597	     * normalized form is what gets stored, returned and used for every address comparison (the
598	     * required-field check, household duplicate detection and the shared household id).
599	     *
600	     * @param address the raw address value from the request, or {@code null}
601	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
602	     */
603	    private String normalizeAddress(String address) {
604	        if (address == null) {
605	            return "";
606	        }
607	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
608	        if (collapsed.isEmpty()) {
609	            return "";
610	        }
611	        String[] tokens = collapsed.split(" ");
612	        for (int i = 0; i < tokens.length; i++) {
613	            switch (tokens[i]) {
614	                case "ST" -> tokens[i] = "STREET";
615	                case "RD" -> tokens[i] = "ROAD";
616	                case "AVE" -> tokens[i] = "AVENUE";
617	                default -> { }
618	            }
619	        }
620	        return String.join(" ", tokens);
621	    }
