623	    /**
624	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
625	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
626	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
627	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
628	     * so two members of one household with different telephones have different keys and are both
629	     * allowed; only an owner whose entire key is identical is a duplicate.
630	     *
631	     * @param owner the owner being created, with its telephone, email and householdId already resolved
632	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
633	     */
634	    private void rejectDuplicateIdentity(Owner owner) {
635	        String identityKey = owner.getIdentityKey();
636	        boolean inUse = this.clinicService.findAllOwners().stream()
637	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
638	        if (inUse) {
639	            throw new DuplicateOwnerIdentityException(identityKey);
640	        }
641	    }
